#include "StockpileRuntime.hpp"
namespace elysium::fortress {bool StockpileRuntime::upsert(StockpilePolicy p){if(!p.id)return false;piles_[p.id]=std::move(p);return true;}bool StockpileRuntime::reserve(Reservation r,std::string&w){auto i=reservations_.find(r.resource);if(i!=reservations_.end()&&i->second.owner!=r.owner){w="reservation conflict";return false;}reservations_[r.resource]=r;return true;}void StockpileRuntime::expire(std::uint64_t t){for(auto i=reservations_.begin();i!=reservations_.end();)if(i->second.expiry&&i->second.expiry<=t)i=reservations_.erase(i);else++i;}std::optional<StableId>StockpileRuntime::chooseDestination(ContentId filter,const std::vector<StableId>&c)const{std::optional<StableId>best;std::uint16_t pri=0;for(auto id:c){auto i=piles_.find(id);if(i==piles_.end()||i->second.filter!=filter)continue;if(!best||i->second.priority>pri||(i->second.priority==pri&&id<*best)){best=id;pri=i->second.priority;}}return best;}}
